def _resolve_profile_picture_avatar(
    profile_picture: object | None,
    request_host: str | None = None,
) -> str | None:
    """Resolve a child profile picture to a device-reachable URL."""
    if not profile_picture:
        return None

    picture_name = getattr(profile_picture, "name", None)
    picture_url = getattr(profile_picture, "url", None)
    if picture_name:
        try:
            return MediaStorageService.generate_presigned_url(
                picture_name,
                request_host=request_host,
            ) or (picture_url if isinstance(picture_url, str) else None)
        except Exception:
            logger.debug(
                "Could not generate presigned profile picture URL", exc_info=True
            )

    if isinstance(picture_url, str):
        return picture_url

    logger.debug("Could not resolve stored profile picture URL")
    return None

