def _resolve_profile_picture_avatar(
    profile_picture: object | None,
    request_host: str | None = None,
    cache: dict[tuple[Any, ...], str | None] | None = None,
) -> str | None:
    """Resolve a child profile picture to a device-reachable URL.

    Reads ``profile_picture.url`` lazily — only as a fallback when presigning
    fails — because ``FileField.url`` can trigger backend-side URL generation
    even when the value is never used. Pass ``cache`` (a dict stashed on the
    request) to dedupe resolution across serializer instances in the same
    request.
    """
    if not profile_picture:
        return None

    picture_name = getattr(profile_picture, "name", None)

    cache_key: tuple[Any, ...] | None = None
    if cache is not None and picture_name:
        cache_key = ("file", picture_name, request_host)
        if cache_key in cache:
            return cache[cache_key]

    resolved: str | None = None
    if picture_name:
        try:
            resolved = MediaStorageService.generate_presigned_url(
                picture_name,
                request_host=request_host,
            )
        except Exception:
            logger.debug(
                "Could not generate presigned profile picture URL", exc_info=True
            )

    if not resolved:
        try:
            picture_url = getattr(profile_picture, "url", None)
        except Exception:
            picture_url = None
        if isinstance(picture_url, str):
            resolved = picture_url

    if resolved is None:
        logger.debug("Could not resolve stored profile picture URL")

    if cache_key is not None and cache is not None:
        cache[cache_key] = resolved

    return resolved

