                            .get("data", {})
                            .get("url")
                        )
        except (AttributeError, ObjectDoesNotExist):
            logger.debug("Could not resolve social account avatar")

    if cache_key is not None and cache is not None:
        cache[cache_key] = avatar_url

    return avatar_url

