def _get_user_avatar(
    user: object,
    request_host: str | None = None,
    cache: dict[tuple[Any, ...], str | None] | None = None,
) -> str | None:
    """Resolve avatar URL from child profile or social account.

    Pass ``cache`` (a dict stashed on the request) to dedupe the full priority
    chain across helper calls in the same request. The cache keys on
    ``(user.id, request_host)`` so concurrent requests to different hosts stay
    isolated.
    """
    user_id = getattr(user, "id", None)
    cache_key: tuple[Any, ...] | None = None
    if cache is not None and user_id is not None:
        cache_key = ("user", user_id, request_host)
        if cache_key in cache:
            return cache[cache_key]

    avatar_url: str | None = None

    # Priority 1: Child profile picture
    child_profile = getattr(user, "child_profile", None)
    if child_profile is not None:
        try:
            child_qs = list(child_profile.all())
            if child_qs:
                child = child_qs[0]
                if getattr(child, "profile_picture", None):
                    avatar_url = _get_profile_picture_avatar(
                        child.profile_picture,
                        request_host=request_host,
                        cache=cache,
                    )
        except (AttributeError, ObjectDoesNotExist):
            logger.debug("Could not resolve child profile avatar")

    # Priority 2: Social account avatar
    if not avatar_url:
        try:
            social_accounts = list(user.socialaccount_set.all())  # type: ignore[attr-defined]
            if social_accounts:
                social_account = social_accounts[0]
                if social_account and social_account.extra_data:
                    avatar_url = social_account.extra_data.get("picture")
                    if not avatar_url and isinstance(
                        social_account.extra_data.get("picture"), dict
                    ):
                        avatar_url = (
                            social_account.extra_data.get("picture", {})
                            .get("data", {})
                            .get("url")
                        )
        except (AttributeError, ObjectDoesNotExist):
            logger.debug("Could not resolve social account avatar")

    if cache_key is not None and cache is not None:
        cache[cache_key] = avatar_url

    return avatar_url

